insert into public.exercise_translations_gymtrack (exercisedb_id, name_pt, instructions_pt) values
  ('lBDjFxJ', 'Barra fixa', array['Suspenda-se em uma barra fixa com as palmas voltadas para fora e os braços estendidos', 'Contraia o tronco e aproxime as escápulas uma da outra', 'Comece a partir de uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Abaixe até estender totalmente os braços sem despencar do topo']),
  ('lCKm4Rs', 'Elevação de uma perna só na bola suíça', array['Posicione-se de bruços em um colchonete com as pernas estendidas e os dedos dos pés apoiados em cima da bola suíça', 'Apoie as mãos no chão, na largura dos ombros, e contraia os músculos do tronco', 'Contraia o abdômen e mantenha os ombros ancorados ao apoio', 'Eleve as pernas contraindo o tronco e movimentando os quadris em vez de balançar', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco; alterne os lados quando necessário']),
  ('LCtQPn8', 'Rosca concentrada inclinada com halteres', array['Sente-se em um banco inclinado com um halter em cada mão, com as palmas voltadas uma para a outra.', 'Apoie os braços no banco, deixando os cotovelos pendurados e as palmas voltadas para a frente.', 'Posicione os ombros e os braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso.', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados.']),
  ('LeaZOIz', 'Rosca alternada com desenvolvimento em pé com halteres', array['Fique em pé com um halter em cada mão, com as palmas voltadas para o corpo.', 'Mantenha os cotovelos próximos ao tronco e as costas retas.', 'Posicione os ombros e os braços antes de flexionar os cotovelos.', 'Faça a rosca com as palmas voltadas uma para a outra e os cotovelos próximos às laterais; evite balançar para trás.', 'Conclua o movimento de um lado antes que o outro lado comece.', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados; alterne os lados quando necessário.']),
  ('LEH9jxP', 'Flexão (na parede)', array['Fique de frente para uma parede, a cerca de um comprimento de braço de distância.', 'Coloque as mãos na parede na altura dos ombros, logo acima da largura dos ombros.', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos se flexionam.', 'Empurre de volta para a posição com os braços esticados, mantendo a linha do corpo intacta.']),
  ('LEprlgG', 'Puxada frontal completa no cabo', array['Sente-se na máquina de puxada com os joelhos posicionados sob os suportes.', 'Segure a barra do cabo com as palmas voltadas para baixo, logo acima da largura dos ombros.', 'Sente-se erguido e posicione os ombros antes de puxar a barra para baixo.', 'Puxe a barra para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco firme.', 'Puxe com os cotovelos em vez de se inclinar muito para trás para mover a barra.', 'Deixe a barra subir de forma constante até que os braços estejam esticados, depois reinicie a posição dos ombros.']),
  ('lFBTISi', 'Elevação de joelho oblíqua suspensa', array['Suspenda-se em uma barra fixa com os braços esticados e as palmas voltadas para a frente.', 'Contraia o tronco e levante os joelhos em direção ao peito, torcendo o tronco para o lado ao fazer isso.', 'Contraia o abdômen e mantenha os ombros ancorados no suporte.', 'Levante as pernas contraindo o tronco e movendo-se a partir dos quadris, em vez de balançar.', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição.', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco.']),
  ('lFhb2Rw', 'Agachamento frontal no Smith (pegada limpa)', array['Prepare a máquina Smith com a barra na altura dos ombros.', 'Fique de frente para a barra com uma base estável e os pés na largura dos ombros.', 'Contraia o abdômen antes do movimento e mantenha a carga próxima ao corpo.', 'Empurre com as pernas e os quadris, depois guie o peso para a posição de recepção.', 'Receba a carga com o tronco contraído e os pés estáveis.', 'Fique em pé para finalizar, depois abaixe o peso com controle antes da próxima repetição.']),
  ('LFIOery', 'Passagem de halter sumô', array['Fique em pé e afaste os pés um pouco mais que a largura dos ombros, com os dedos apontados para fora.', 'Segure um halter com as duas mãos à frente do corpo, com os braços estendidos.', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás.', 'Empurre os quadris para trás mantendo a carga próxima e a coluna firme.', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a curvar.', 'Empurre os quadris para frente para ficar em pé sem se inclinar para trás no topo.']),
  ('lHeUULr', 'Levantamento terra romeno com perna rígida e elástico', array['Fique em pé com os pés na largura dos ombros e coloque o elástico ao redor da parte superior das pernas.', 'Segure o elástico com as duas mãos à frente das coxas, com as palmas voltadas para o corpo.', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás.', 'Empurre os quadris para trás mantendo a carga próxima e a coluna firme.', 'Controle o elástico na subida em vez de deixar que ele puxe você bruscamente para a posição.', 'Empurre os quadris para frente para ficar em pé sem se inclinar para trás no topo.']),
  ('LHWF7us', 'Remada alta com kettlebell', array['Fique de pé com os pés na largura dos ombros, segurando um kettlebell na altura das coxas', 'Flexione levemente os joelhos e incline o tronco à frente a partir do quadril, mantendo a coluna firme', 'Contraia o abdômen antes de puxar e mantenha a carga próxima ao corpo', 'Empurre o chão com as pernas e o quadril, depois conduza o peso para a posição de recepção', 'Receba a carga com o tronco contraído e os pés estáveis', 'Fique erguido para finalizar, depois desça o peso com controle antes da próxima repetição']),
  ('lI7easp', 'Pullover com halteres e extensão de quadril na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e o haltere apoiado nas coxas', 'Com controle, caminhe para a frente com os pés, rolando a bola suíça pelas costas até que sua cabeça, pescoço e parte superior das costas estejam apoiados na bola', 'Encaixe as costelas e mantenha uma leve flexão nos cotovelos antes de descer o peso', 'Desça o peso em um arco atrás da cabeça até sentir um alongamento confortável nos ombros', 'Mantenha a bola estável e use os pés para controlar seu equilíbrio', 'Puxe o peso de volta sobre o peito pelo mesmo arco, sem levantar as costelas']),
  ('LIGZSTA', 'Rosca martelo unilateral com halteres no banco inclinado', array['Posicione-se de bruços em um banco reto com um haltere em uma mão, palma voltada para o corpo e braço esticado', 'Mantenha o braço fixo e flexione o haltere em direção ao ombro, contraindo o bíceps', 'Posicione os ombros e os braços antes de dobrar os cotovelos', 'Flexione com as palmas voltadas uma para a outra e os cotovelos próximos ao corpo; evite balançar', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço em movimento', 'Desça até que os braços fiquem quase retos, mantendo a parte superior dos braços parada; alterne os lados quando necessário']),
  ('LIlE5Tn', 'Agachamento com salto', array['Fique de pé com os pés na largura dos ombros', 'Antes de se mover, abaixe o corpo em posição de agachamento flexionando os joelhos e empurrando o quadril para trás', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione o quadril e os joelhos para descer, mantendo os pés firmes no chão e os joelhos alinhados com os dedos dos pés', 'Impulsione-se para cima com o peito e o quadril subindo juntos; evite que os joelhos fechem para dentro', 'Fique totalmente em pé, ajuste sua postura e respiração, então inicie a próxima descida']),
  ('lJJ7Yq8', 'Crucifixo deitado com cabos', array['Conecte os puxadores aos cabos e deite-se de costas em um banco com os pés apoiados', 'Segure os puxadores com as palmas voltadas uma para a outra e os braços esticados acima do peito', 'Mantenha uma leve flexão nos cotovelos e ajuste os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, aproxime os braços em um arco amplo', 'Mantenha o ângulo do cotovelo quase inalterado durante todo o arco', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair']),
  ('LkoAWAE', 'Mergulho de cotovelo', array['Sente-se na borda de um banco ou cadeira com as mãos apoiadas na borda ao lado do quadril', 'Mova o quadril para a frente para fora do banco e estique as pernas, mantendo os calcanhares no chão', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás', 'Flexione os cotovelos para descer entre os apoios; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita manter os ombros confortáveis', 'Empurre com as mãos para subir, depois ajuste os ombros antes da próxima repetição']),
  ('LL1UiTX', 'Supino inclinado unilateral com halteres com pegada neutra', array['Sente-se em um banco inclinado com um haltere em uma mão, apoiado na sua coxa', 'Deite-se no banco e use sua coxa para ajudar a elevar o haltere até a altura do ombro', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco contraído', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço em movimento', 'Desça o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando necessário']),
  ('LLNh6q5', 'Crucifixo inclinado unilateral com halteres na bola suíça', array['Sente-se em uma bola suíça com um haltere em uma mão', 'Dê um passo à frente com os pés e role o corpo para baixo até que sua cabeça, pescoço e parte superior das costas estejam apoiados na bola', 'Mantenha uma leve flexão nos cotovelos e ajuste os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, aproxime os braços em um arco amplo', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço em movimento', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair; alterne os lados quando necessário']),
  ('LlSe9IK', 'Barra fixa assistida em pé', array['Ajuste a máquina para o nível de assistência desejado', 'Suba na plataforma para os pés e segure as alças com as palmas voltadas para baixo, logo além da largura dos ombros', 'Comece a partir de uma suspensão controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Desça até os braços esticados sem cair repentinamente do topo']),
  ('LmaFNZS', 'Elevação de panturrilha com carga em decúbito (donkey calf raise)', array['Suba em uma plataforma elevada com os dedos dos pés na borda e os calcanhares para fora', 'Use um objeto estável para apoio', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece imóvel', 'Suba na ponta dos pés, elevando os calcanhares o mais alto possível sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Baixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('LMGXZn8', 'Tríceps testa com pegada fechada e barra declinada', array['Posicione-se em um banco declinado com a cabeça mais baixa que os pés e segure uma barra com pegada fechada', 'Abaixe a barra em direção à testa flexionando os cotovelos, com a parte superior dos braços estática', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('Ln9iTbU', 'Elevação posterior com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas voltadas para baixo', 'Flexione levemente os joelhos e incline o tronco à frente a partir do quadril, com a coluna firme', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Levante os braços para fora e para trás com os cotovelos semiflexionados, deixando os ombros posteriores fazerem o trabalho', 'Pare perto da altura dos ombros em vez de encolher para levantar mais alto', 'Abaixe os braços lentamente para os lados sem balançar o peso']),
  ('LNE3wfo', 'Deslizamento unilateral na plataforma', array['Comece em pé com um pé em uma plataforma ou prancha de deslizamento', 'Antes de se mover, flexione levemente o joelho e deslize o pé na plataforma para trás, estendendo a perna', 'Posicione sua base com largura suficiente para equilibrar antes de flexionar qualquer joelho', 'Entre no movimento e flexione ambos os joelhos, mantendo o pé da frente apoiado', 'Mantenha o pé da frente apoiado e evite colapsar o joelho para dentro', 'Empurre através do pé da frente para retornar ao início, depois troque de perna conforme planejado']),
  ('LQFOrMn', 'Mergulho no peito em barra reta', array['Segure as barras paralelas com as palmas voltadas para baixo e os braços esticados', 'Antes de se mover, flexione os joelhos e cruze os tornozelos', 'Posicione os ombros para baixo e mantenha os cotovelos apontados principalmente para trás', 'Flexione os cotovelos para descer entre os suportes; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita aos ombros permanecerem confortáveis', 'Empurre com as mãos para subir, depois ajuste os ombros antes de outra repetição']),
  ('lRcrlH8', 'Levantamento terra com pernas esticadas e elástico', array['Fique em pé com os pés na largura dos ombros e coloque o elástico sob os pés', 'Segure o elástico com as duas mãos, palmas voltadas para o corpo, e mantenha os braços esticados', 'Destrave os joelhos e contraia o abdômen antes de mover o quadril para trás', 'Envie o quadril para trás com uma leve flexão dos joelhos, abaixando a carga perto das pernas até os posteriores de coxa alongarem', 'Controle o elástico na subida em vez de deixar que ele puxe você para a posição', 'Empurre o quadril para frente para ficar erguido sem inclinar para trás no topo']),
  ('LrV4s90', 'Rosca de punho na polia', array['Conecte uma barra reta a um aparelho de polia baixa', 'Fique de frente para a máquina em uma postura estável com os pés na largura dos ombros', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço assumam a carga', 'Mova-se através dos punhos ou dedos enquanto os antebraços permanecem apoiados e imóveis', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne suavemente ao início sem deixar a carga cair das mãos']),
  ('Lsqrgh4', 'Elevação de panturrilha invertida no Smith', array['Ajuste a barra da máquina Smith em uma altura logo abaixo dos seus ombros', 'Fique de frente para a barra com os pés na largura dos quadris e as pontas dos pés apontadas para a frente', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece firme', 'Suba apoiando-se na parte anterior dos pés, elevando os calcanhares o máximo que puder sem balançar', 'Pause no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('LSTChY9', 'Agachamento Zercher com barra', array['Fique de pé e ajuste seus pés na largura dos ombros com as pontas dos pés levemente viradas para fora', 'Segure a barra na dobra dos cotovelos, com as mãos firmes na barra para dar estabilidade', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados no chão e os joelhos alinhados com as pontas dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua postura e respiração, depois inicie a próxima descida']),
  ('LsZkfU6', 'Rosca inversa de punho com barra', array['Apoie ambos os pés no chão enquanto estiver sentado em um banco; segure uma barra com as palmas das mãos viradas para baixo', 'Apoie os antebraços nas coxas, deixando os punhos para fora da borda', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Faça um movimento curto e suave sem balançar os cotovelos', 'Retorne à posição inicial com controle sem deixar a carga escapar das suas mãos']),
  ('Lt3iWnf', 'Crucifixo com halteres na bola suíça', array['Sente-se em uma bola suíça e segure um halter em cada mão', 'Dê um passo à frente com os pés e role o corpo para baixo até que sua cabeça, pescoço e parte superior das costas estejam apoiados na bola', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, junte os braços em um arco amplo', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair']),
  ('LuBEORI', 'Remada curvada no aparelho com barra V', array['Ajuste o assento ao seu corpo e acomode-se no aparelho', 'Segure a barra V com as palmas das mãos viradas para baixo, com a coluna firme e os joelhos levemente flexionados', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a manopla ou o peso em direção ao seu tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('LWuA3aZ', 'Rosca direta indevida com barra em pé', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas das mãos viradas para cima', 'Mantenha os cotovelos próximos ao tronco e os braços parados', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione o peso com as palmas das mãos viradas para baixo, mantendo os cotovelos próximos e o tronco parado', 'Mantenha as palmas na pegada escolhida sem curvar os punhos para trás', 'Abaixe até que os braços estejam quase retos, mantendo a parte superior dos braços parada']),
  ('LYJodFS', 'Planche inclinado', array['Comece em uma posição de flexão com as mãos na largura dos ombros e o corpo reto', 'Contraia o tronco e, com controle, desloque seu peso para a frente, levando os ombros além das mãos', 'Contraia o abdômen e encontre uma posição que consiga manter sem prender a respiração', 'Contraia a região central do corpo e mantenha a posição enquanto respira normalmente', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal', 'Mantenha a postura pelo tempo planejado e saia dela com controle']),
  ('lyKCLmK', 'Rosca concentrada inversa com halter sentado', array['Sente-se com ambos os pés apoiados no chão e segure um halter com a palma da mão virada para baixo', 'Apoie o cotovelo na parte interna da coxa, logo acima do joelho', 'Posicione os ombros e o braço antes de flexionar o cotovelo', 'Flexione o halter com a palma da mão virada para baixo enquanto a parte superior do braço permanece apoiada na parte interna da coxa', 'Mantenha as palmas na pegada escolhida sem curvar os punhos para trás', 'Abaixe até que o braço esteja quase reto, mantendo a parte superior do braço parada']),
  ('LzX8YEz', 'Alongamento de quadríceps em quatro apoios', array['Fique de joelhos e com as mãos apoiadas, com as mãos diretamente sob os ombros e os joelhos diretamente sob os quadris', 'Estenda uma perna para trás, mantendo o joelho flexionado e o pé flexionado', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Avance em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha um alongamento leve em vez de puxar com mais força usando impulso', 'Segure a posição com respiração constante e solte devagar; repita do outro lado, se necessário']),
  ('m0tCHqc', 'Alongamento de panturrilha com as mãos na parede', array['Fique de frente para uma parede com os pés na largura dos quadris', 'Apoie as mãos na parede na altura dos ombros', 'Ajuste-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Abaixe o calcanhar e desloque o peso até alongar a panturrilha; mantenha o pé apontado para frente', 'Mantenha um alongamento leve em vez de puxar com mais força usando impulso', 'Segure a posição com respiração constante e solte devagar; repita do outro lado, se necessário']),
  ('M2Pm3zj', 'Supinação deitada com halteres', array['Acomode-se em um banco com os pés apoiados no chão', 'Segure um halter em cada mão com as palmas voltadas para cima e os braços estendidos', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço absorvam a carga', 'Movimente apenas pelos punhos ou dedos, mantendo os antebraços apoiados e imóveis', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne devagar ao início sem deixar a carga escapar das mãos']),
  ('M5Y7GPg', 'Rosca em pé com peso', array['Fique em pé com os pés na largura dos ombros e segure um halter em cada mão, com as palmas voltadas para frente', 'Mantenha os cotovelos próximos ao tronco, expire e flexione os pesos até a altura dos ombros', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para levar o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os braços estejam quase esticados, mantendo a parte superior dos braços imóvel']),
  ('M72BExt', 'Rotação de tronco deitada em decúbito ventral com uma perna na bola suíça', array['Posicione-se de bruços na bola suíça com os quadris apoiados na bola e as pernas estendidas para trás', 'Apoie as mãos no chão à sua frente para dar suporte', 'Ajuste a pelve e faça a rotação através da caixa torácica', 'Gire o tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível', 'Mantenha a pelve nivelada enquanto a perna de apoio faz o trabalho', 'Retorne pelo centro antes de girar para o outro lado; alterne os lados quando necessário']),
  ('M74kdvm', 'Arranco duplo com kettlebell', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell em cada mão com os braços estendidos à frente das coxas', 'Antes de se mover, flexione levemente os joelhos e incline o tronco à frente nos quadris, mantendo as costas retas e o peito estufado', 'Estabilize o core antes de puxar e mantenha a carga próxima ao corpo', 'Empurre com as pernas e os quadris, e então guie o peso para a posição de recepção', 'Receba a carga com o tronco firme e os pés estáveis', 'Fique erguido para finalizar e abaixe o peso com controle antes da próxima repetição']),
  ('M8IolhQ', 'Rosca scott com barra W e pegada fechada', array['Sente-se no banco scott e apoie a parte superior dos braços no apoio, segurando a barra W com as palmas voltadas para cima', 'Apoie os tríceps no suporte e estique os braços, mantendo a coluna firme', 'Posicione o braço em trabalho contra o apoio scott e deixe o cotovelo livre para flexionar', 'Flexione o peso enquanto a parte superior dos braços permanece em contato com o apoio', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os braços estejam quase esticados, mantendo a parte superior dos braços imóvel']),
  ('MaMuGH6', 'Puxada com assistência de máquina', array['Ajuste a máquina com o nível de resistência desejado', 'Suba na plataforma para os pés e segure as alças com as palmas voltadas para baixo, logo além da largura dos ombros', 'Comece a partir de uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e leve a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Desça com os braços estendidos sem soltar de repente a partir do topo']),
  ('mAYqY4M', 'Flexão planche completa', array['Apoie as palmas das mãos perto dos quadris e incline-se para a frente até que os ombros ultrapassem os punhos', 'Retire ambos os pés do chão com as pernas esticadas e o tronco firme', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta para a extensão completa dos braços, mantendo a linha do corpo intacta']),
  ('mbkgB44', 'Abdominal canivete', array['Deite-se de costas com as pernas estendidas e os braços esticados acima da cabeça', 'Contraia o tronco e eleve as pernas e a parte superior do corpo simultaneamente, alcançando as mãos em direção aos dedos dos pés', 'Posicione a pelve e mantenha o pescoço relaxado antes de iniciar a flexão para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('MCkqdKE', 'Muscle-up com carga (na barra)', array['Comece pendurado em uma barra fixa com as palmas das mãos viradas para fora e ligeiramente além da largura dos ombros', 'Contraia o tronco e puxe as escápulas para baixo e para trás', 'Comece de uma suspensão controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Abaixe até esticar os braços sem despencar do topo']),
  ('MCUhf1F', 'Abdominal (na bola suíça)', array['Sente-se na bola suíça com os pés apoiados no chão e os joelhos flexionados a um ângulo de 90 graus', 'Recline-se na bola até que a parte inferior das costas esteja apoiada e a parte superior do corpo fique paralela ao chão', 'Posicione a pelve e mantenha o pescoço relaxado antes de iniciar a flexão para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Mantenha a bola estável e use os pés para controlar o equilíbrio', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('MDFxU4b', 'Agachamento livre', array['Fique de pé e posicione os pés na largura dos ombros', 'Antes de se mover, abaixe o corpo flexionando os joelhos e empurrando os quadris para trás como se estivesse sentando em uma cadeira', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e joelhos para descer, mantendo os pés firmes e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida']),
  ('mExgrF9', 'Remada invertida na barra', array['Posicione-se embaixo de uma barra ou de uma superfície horizontal firme que esteja na altura do peito', 'Segure a barra ou a superfície com as palmas voltadas para baixo, ligeiramente além da largura dos ombros', 'Comece de uma suspensão controlada com os ombros ativos em vez de relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para subir', 'Abaixe até esticar os braços sem despencar do topo']),
  ('mgejmGP', 'Meio abdominal prisioneiro', array['Deite-se de costas com os joelhos flexionados e os pés apoiados no chão', 'Coloque as mãos atrás da cabeça com os cotovelos apontando para fora', 'Posicione a pelve e mantenha o pescoço relaxado antes de iniciar a flexão para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('MgKwAAo', 'Remada inclinada com cabo e corda', array['Prepare um banco inclinado a um ângulo de 45 graus e acople uma máquina de cabo na polia baixa', 'Conecte um puxador de corda à máquina de cabo e sente-se no banco inclinado de frente para o aparelho', 'Posicione o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga a corda ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos com o tronco', 'Estenda os braços para a frente novamente sem deixar o tronco avançar bruscamente']),
  ('MKIelrR', 'Supino unilateral no cabo na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas.', 'Segure o puxador do cabo com uma mão e posicione o braço na altura do peito com o cotovelo flexionado.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso para frente mantendo o tronco firme.', 'Mantenha ambos os ombros nivelados e evite girar o corpo para o lado do braço em movimento.', 'Abaixe o peso de forma controlada até a altura inicial antes de empurrar novamente; alterne os lados quando necessário.']),
  ('mKwcrHn', 'Aperto de mãos na máquina', array['Ajuste a altura do assento e segure os puxadores da máquina.', 'Mantenha a coluna em uma posição neutra e confortável, com os pés apoiados.', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga.', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e parados.', 'Execute um movimento curto e suave sem balançar os cotovelos.', 'Retorne à posição inicial lentamente sem deixar a carga cair das mãos.']),
  ('mnzcrIB', 'Agachamento com halteres no banco', array['Posicione um halter no chão em frente a um banco.', 'Fique de costas para o banco em uma base estável, com os pés na largura dos ombros.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e os joelhos para abaixar o corpo, mantendo os pés firmes e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima elevando o peito e os quadris simultaneamente; evite que os joelhos desabem para dentro.', 'Fique totalmente em pé, ajuste sua postura e respiração, e então inicie a próxima descida.']),
  ('mpKZGWz', 'Tríceps testa com halteres', array['Deite-se em um banco com um halter em cada mão e as palmas voltadas uma para a outra.', 'Estenda os braços para cima sobre o peito, mantendo os cotovelos próximos ao corpo.', 'Posicione os braços firmemente antes de estender os cotovelos.', 'Mantenha a parte superior dos braços estável e estenda os cotovelos para mover o peso.', 'Mantenha a parte superior dos braços firme enquanto os antebraços se movimentam.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição.']),
  ('mpYUPkA', 'Elevação de quadril deitado', array['Deite-se de costas com as pernas estendidas e os braços ao lado do corpo.', 'Coloque as mãos sob os glúteos para dar suporte.', 'Apoie os pés no chão e evite estufar as costelas enquanto prepara os quadris para subir.', 'Pressione através dos pés e eleve os quadris até que seu tronco e suas coxas estejam alinhados.', 'Pare quando os quadris estiverem alinhados com o tronco; não arqueie excessivamente a parte inferior das costas.', 'Abaixe os quadris de forma constante e mantenha os pés apoiados para a próxima elevação.']),
  ('mQ1tBXn', 'Abdução de quadril com perna estendida', array['Deite-se de lado com as pernas estendidas e empilhadas uma sobre a outra.', 'Apoie a cabeça sobre o braço de baixo para maior suporte.', 'Alinhe a pelve antes de movimentar a perna de trabalho.', 'Movimente a perna de trabalho para o lado a partir do quadril, sem balançar o tronco.', 'Movimente apenas até onde a pelve conseguir permanecer estável.', 'Retorne pelo mesmo caminho em um ritmo controlado.']),
  ('MqNdIbe', 'Rosca de punho com rolo', array['Conecte um peso a uma das pontas de uma corda ou barra.', 'Segure a outra ponta da corda ou barra com as duas mãos e as palmas voltadas para baixo.', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga.', 'Movimente os punhos ou dedos enquanto os antebraços permanecem apoiados e parados.', 'Execute um movimento curto e suave sem balançar os cotovelos.', 'Retorne à posição inicial lentamente sem deixar a carga cair das mãos.']),
  ('mr7pkqP', 'Burpee com polichinelo', array['Comece em posição em pé com os pés na largura dos ombros.', 'Antes de se mover, abaixe o corpo em posição de agachamento, colocando as mãos no chão à sua frente.', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia.', 'Movimente-se em um ritmo constante, mantendo o movimento fluido e a respiração controlada.', 'Mantenha o padrão constante conforme a velocidade aumenta.', 'Mantenha o ritmo durante o intervalo planejado, diminuindo a velocidade se a sua execução começar a falhar.']),
  ('Mr8d4KA', 'Desenvolvimento Arnold com kettlebell', array['Fique de pé com os pés na largura dos ombros, segurando um kettlebell em cada mão na altura dos ombros com as palmas voltadas para você', 'Contraia o abdômen e empurre os kettlebells para cima, rotacionando as palmas para frente conforme estende os braços', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('MRaFiZP', 'Desenvolvimento sentado no Smith', array['Ajuste a altura do assento para que os puxadores fiquem na altura dos ombros', 'Sente-se na máquina com as costas apoiadas no encosto e os pés firmes no chão', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('MrgP9L6', 'Panturrilha sentada na máquina', array['Ajuste a altura do assento para que seus joelhos fiquem levemente flexionados e os pés apoiados na plataforma', 'Posicione as pontas dos pés na plataforma, com os calcanhares para fora da borda', 'Deixe os tornozelos se moverem livremente enquanto o resto do corpo permanece firme', 'Eleve-se na ponta dos pés, levantando os calcanhares o mais alto possível sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('ms7tjSG', 'Flexão de pernas invertida (com apoio no banco)', array['Posicione-se de bruços em um banco com os quadris na borda e as pernas estendidas para trás', 'Use o banco como apoio', 'Alinhe os joelhos com a borda da máquina ou do banco antes de iniciar a flexão', 'Flexione os joelhos para trazer o apoio em sua direção sem levantar os quadris do suporte', 'Mantenha os quadris parados enquanto os joelhos se flexionam', 'Retorne o peso ou o corpo à posição inicial sem pressa']),
  ('MSfvriJ', 'Skin the cat', array['Comece pendurado em uma barra com os braços retos e o corpo relaxado', 'Contraia o abdômen e levante as pernas, trazendo os joelhos em direção ao peito', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Avance em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado se necessário']),
  ('mTT3KLn', 'Elevação frontal no cabo', array['Fique de pé com os pés na largura dos ombros e segure o puxador do cabo com as palmas para baixo', 'Mantenha a coluna em uma posição neutra confortável e o core ativado', 'Comece com uma carga moderada e uma leve flexão nos cotovelos', 'Eleve os pesos para longe do tronco até a altura dos ombros, mantendo os cotovelos levemente flexionados', 'Pare próximo à altura dos ombros em vez de encolher os ombros para levantar mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('mtXengz', 'Rosca de dedos com halter', array['Sente-se em um banco ou cadeira com os pés firmes e as costas retas', 'Segure um halter em uma mão com a palma voltada para cima, apoiando o antebraço na coxa', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão e do antebraço suportem a carga', 'Deixe a barra rolar até as pontas dos dedos e, em seguida, feche os dedos firmemente ao redor dela', 'Use uma amplitude curta e suave sem balançar os cotovelos', 'Retorne ao início sem deixar a carga cair das mãos']),
  ('mu5Guxt', 'Elevação lateral posterior com halteres', array['Fique de pé com os pés na largura dos ombros e segure um halter em cada mão, com as palmas voltadas para o corpo', 'Flexione levemente os joelhos e incline o tronco à frente a partir do quadril, mantendo a coluna firme', 'Comece com uma carga moderada e uma leve flexão nos cotovelos', 'Eleve os braços para fora e para trás com os cotovelos macios, deixando a parte posterior dos ombros fazer o trabalho', 'Pare próximo à altura dos ombros em vez de encolher os ombros para levantar mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('MU9HnE7', 'Mergulho no banco com peso', array['Sente-se em um banco com as mãos segurando a borda e os dedos apontados para a frente.', 'Afaste o quadril do banco, sustentando seu peso com as mãos.', 'Encaixe os ombros para baixo e mantenha os cotovelos apontados principalmente para trás.', 'Flexione os cotovelos para descer entre os apoios e pare em uma profundidade confortável para os ombros.', 'Escolha uma profundidade que permita que os ombros fiquem confortáveis.', 'Pressione com as mãos para subir e, em seguida, ajuste os ombros antes de outra repetição.']),
  ('MUic5zN', 'Flexão com um braço', array['Comece em uma posição de flexão com as mãos na largura dos ombros e uma mão colocada ligeiramente mais aberta do que a outra.', 'Contraia o tronco e abaixe o corpo em direção ao chão flexionando os cotovelos, com a coluna firme.', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito, mantendo o corpo em linha reta.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam.', 'Empurre de volta para os braços esticados, mantendo a linha do corpo intacta.']),
  ('MvQPqVW', 'Giro judô no cabo', array['Fique de frente para a máquina de cabo com uma base estável e os pés na largura dos ombros.', 'Segure a manopla do cabo com ambas as mãos na altura do peito e as palmas voltadas para baixo.', 'Posicione a pelve e faça a rotação através da caixa torácica.', 'Gire através do tronco enquanto os quadris e a parte inferior do corpo permanecem o mais firmes possível.', 'Mantenha o giro suave em vez de lançar os braços através do corpo.', 'Retorne pelo centro antes de girar para o outro lado.']),
  ('mWBtgmb', 'Caminhada com um haltere acima da cabeça', array['Fique em pé e posicione os pés na largura dos ombros, segurando um haltere em uma das mãos.', 'Antes de se mover, eleve o haltere acima da cabeça, estendendo totalmente o braço.', 'Fique em pé com a carga segura e os ombros nivelados.', 'Caminhe em um ritmo controlado, mantendo os ombros nivelados e os passos uniformes.', 'Mantenha os passos uniformes e evite inclinar-se para longe da carga.', 'Pare antes que a postura falhe, apoie a carga com segurança e ajuste-se para a próxima caminhada.']),
  ('mweqJin', 'Pés rápidos', array['Fique em pé com os pés na largura dos ombros e os braços ao lado do corpo.', 'Comece movendo rapidamente os pés para cima e para baixo, como se estivesse correndo no lugar.', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia.', 'Mova-se em um ritmo repetível, mantendo o movimento suave e a respiração constante.', 'Mantenha o padrão repetível à medida que a velocidade aumenta.', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar.']),
  ('mWppALS', 'Abdominal para adutores', array['Deite-se de costas com os joelhos flexionados e os pés apoiados.', 'Coloque as mãos atrás da cabeça com os cotovelos apontados para fora.', 'Posicione a pelve e mantenha o pescoço relaxado antes de flexionar para cima.', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco.', 'Deixe um pequeno espaço entre o queixo e o peito e mantenha o movimento no tronco.', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão.']),
  ('mwpPcr1', 'Rosca com halteres no banco inclinado de bruços', array['Ajuste o banco para uma inclinação de 45 graus.', 'Posicione-se de bruços no banco com o peito e o estômago apoiados nele.', 'Posicione os ombros e os braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha o tronco imóvel e permita que a flexão do cotovelo levante o peso.', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados.']),
  ('Mxa7Cr8', 'Remada invertida no banco', array['Prepare um banco em uma altura que permita que seu corpo fique pendurado livremente embaixo dele.', 'Deite-se de costas no chão com a cabeça em direção ao banco.', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a manopla ou o peso em direção ao seu tronco.', 'Traga os cotovelos para trás sem dar trancos no tronco.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar.']),
  ('my33uHU', 'Cadeira extensora', array['Ajuste a altura do assento e do encosto da máquina para o seu corpo', 'Sente-se na máquina com as costas apoiadas no encosto e os pés no suporte', 'Posicione o rolo logo acima dos tornozelos e mantenha as coxas apoiadas no assento', 'Estenda os joelhos para levantar o peso, mantendo o quadril apoiado no assento', 'Eleve sem balançar e evite esticar os joelhos de forma brusca', 'Retorne o peso ou o corpo à posição inicial sem pressa']),
  ('MY9P1WA', 'Supino declinado com pegada inversa no Smith', array['Ajuste a máquina Smith para a posição declinada', 'Deite-se no banco com os pés presos sob os suportes', 'Estabilize o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as manoplas para longe, mantendo o tronco firme', 'Mantenha as palmas das mãos na pegada escolhida sem flexionar os punhos para trás', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('myfUsKf', 'Crucifixo inverso sentado na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure as manoplas com as palmas voltadas para baixo e mantenha os braços relaxados', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Abra os braços para fora e para trás com uma leve flexão nos cotovelos, aproximando as escápulas', 'Mantenha o ângulo dos cotovelos quase inalterado durante todo o arco', 'Abra os braços para trás seguindo o mesmo arco sem deixar a carga cair']),
  ('myJeTAe', 'Elevação lateral unilateral no cabo', array['Fique em pé com os pés na largura dos ombros, de frente para a máquina de cabo', 'Segure a manopla do cabo com uma mão, palma voltada para baixo, e afaste-se o suficiente para manter o cabo tenso', 'Comece com uma carga adequada e uma leve flexão nos cotovelos', 'Eleve os braços para as laterais até a altura dos ombros, sem inclinar o tronco ou encolher os ombros', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço em movimento', 'Abaixe os braços lentamente para as laterais sem balançar o peso; alterne os lados conforme necessário']),
  ('mym4hJo', 'Supinação deitado com halteres', array['Acomode-se em um banco com o peito voltado para baixo e os braços estendidos para baixo, segurando um halter em cada mão', 'Antes de se mover, gire as palmas das mãos para cima', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga', 'Movimente-se através dos punhos ou dedos enquanto os antebraços permanecem apoiados e parados', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne à posição inicial sem deixar a carga escapar das mãos']),
  ('Mz6lLcW', 'Afundo com halteres e rosca direta', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas voltadas para frente', 'Dê um passo à frente com o pé direito, abaixando o corpo em uma posição de afundo. Seu joelho direito deve estar dobrado em um ângulo de 90 graus e o esquerdo pairando logo acima do chão', 'Abra a base o suficiente para manter o equilíbrio antes de flexionar qualquer um dos joelhos', 'Avance para o movimento e dobre ambos os joelhos, mantendo o pé da frente fixo no chão', 'Mantenha o pé da frente fixo e evite que o joelho ceda para dentro', 'Empurre o chão com o pé da frente para retornar à posição inicial, depois alterne as pernas conforme planejado']),
  ('MzNnwx9', 'Encolhimento de ombros por trás no Smith', array['Fique em pé com os pés na largura dos ombros e os joelhos levemente flexionados', 'Segure a barra com as palmas voltadas para trás, com as mãos um pouco além da largura dos ombros', 'Deixe os braços estendidos para baixo e mantenha a cabeça neutra', 'Eleve os ombros em direção às orelhas sem dobrar os cotovelos ou girar os ombros', 'Suba e desça na vertical sem fazer movimentos circulares com os ombros', 'Retorne suavemente à posição inicial antes de repetir']),
  ('N3EirIW', 'Puxada alta com apoio na máquina', array['Ajuste a máquina com contrapeso para o nível de resistência desejado', 'Suba na plataforma e segure as manoplas com as palmas voltadas para frente, um pouco além da largura dos ombros', 'Comece de uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e aproxime a parte superior do peito da barra sem chutar com as pernas', 'Evite balançar as pernas para ultrapassar a barra', 'Desça com os braços estendidos sem despencar do alto']),
  ('n5cWCsI', 'Elevação lateral com um halter', array['Fique em pé e posicione os pés na largura dos ombros, segurando um halter em uma mão com a palma voltada para o corpo', 'Mantenha a coluna em uma posição neutra confortável e o core contraído durante todo o exercício', 'Comece com uma carga viável e uma leve flexão nos cotovelos', 'Eleve os braços para os lados até a altura dos ombros sem inclinar ou encolher os ombros', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Abaixe os braços lentamente para as laterais sem balançar o peso; troque de lado quando a série exigir']),
  ('N6dZN2I', 'Remada alta no cabo (ajoelhado)', array['Instale uma barra reta na polia na altura do peito', 'Ajoelhe-se na frente da máquina de cabo e segure a barra com as palmas voltadas para baixo, com as mãos na largura dos ombros', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao seu tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('NAgVB3t', 'Roda abdominal', array['Ajoelhe-se no chão e coloque a roda abdominal na sua frente', 'Coloque as mãos nos puxadores da roda abdominal e estenda os braços diretamente para a frente', 'Contraia o abdômen e mantenha a pelve encaixada antes de afastar os braços', 'Estenda os braços para longe, mantendo as costelas e a pelve alinhadas; pare antes que a parte inferior das costas arqueie', 'Pare de estender quando a parte inferior das costas começar a arquear', 'Puxe de volta para o início usando os ombros e o abdômen, mantendo a mesma linha corporal']),
  ('NAkmgdx', 'Abdominal completo com braços estendidos acima da cabeça', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Estenda os braços acima da cabeça, mantendo-os retos', 'Posicione a pelve e mantenha o pescoço relaxado antes de enrolar para cima', 'Enrole a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('nAuHPcD', 'Extensão de tríceps com um halter (no banco)', array['Sente-se em um banco com a coluna reta e os pés apoiados', 'Pegue um halter em uma mão e coloque a outra mão no banco para se apoiar', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda através dos cotovelos para mover o peso', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição; troque de lado quando a série exigir']),
  ('NbVPDMW', 'Rosca direta com halteres', array['Fique em pé com um halter em cada mão, palmas voltadas para a frente e braços estendidos', 'Com a parte superior dos braços parada, expire e flexione os pesos enquanto contrai os bíceps', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços parada']),
  ('NCmbLCw', 'Flexão (na parede)', array['Fique de frente para uma parede, a aproximadamente um comprimento de braço de distância', 'Coloque as mãos na parede na altura dos ombros, um pouco além da largura dos ombros', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta para a extensão completa dos braços, mantendo a linha do corpo intacta']),
  ('nCU1Ekp', 'Abdominal reverso', array['Deite-se de costas com os braços estendidos ao longo do corpo', 'Antes de se mover, flexione os joelhos e retire os pés do chão, trazendo as coxas perpendiculares ao chão', 'Posicione a pelve e mantenha o pescoço relaxado antes de enrolar para cima', 'Enrole a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima repetição']),
  ('NdIb5Z1', 'Rosca direta com pegada aberta com barra', array['Fique em pé com os pés na largura dos ombros e segure uma barra com as palmas voltadas para baixo, com as mãos mais afastadas que a largura dos ombros.', 'Mantenha a barra pendurada com os braços estendidos à frente das coxas, com as palmas voltadas para fora do corpo.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco.', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso.', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel.']),
  ('nDK1HJ0', 'Pullover deitado com braços flexionados com barra EZ', array['Deite-se em um banco com a cabeça em uma ponta e os pés no chão.', 'Segure a barra EZ com uma pegada prono (palmas voltadas para fora) e as mãos na largura dos ombros.', 'Abaixe as costelas e mantenha uma leve flexão nos cotovelos antes de abaixar o peso.', 'Abaixe o peso em arco atrás da cabeça até sentir um alongamento confortável nos ombros.', 'Mantenha as costelas abaixadas enquanto os braços se movem por cima da cabeça.', 'Puxe o peso de volta sobre o peito ao longo do mesmo arco, sem levantar as costelas.']),
  ('neonEDL', 'Crucifixo no solo com barra', array['Deite-se de costas no chão com os joelhos flexionados e os pés apoiados.', 'Segure uma barra com as palmas voltadas para baixo, com os braços estendidos direto para cima sobre o peito.', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços.', 'Com uma leve flexão nos cotovelos, junte os braços em um arco amplo.', 'Mantenha o ângulo do cotovelo quase inalterado durante o arco.', 'Abra os braços de volta ao longo do mesmo arco sem deixar cair a carga.']),
  ('nFc4FyV', 'Rosca direta inversa com halteres', array['Fique em pé com um halter em cada mão, palmas voltadas para baixo e braços estendidos.', 'Com a parte superior dos braços estática, expire e flexione os pesos enquanto contrai os bíceps.', 'Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', 'Flexione o peso com as palmas voltadas para baixo, mantendo os cotovelos próximos e o tronco imóvel.', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso.', 'Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel.']),
  ('nFHk9fU', 'Puxada frontal no cabo com corda', array['Conecte um acessório de corda à máquina de cabo em uma posição alta.', 'Fique de frente para a máquina em uma postura estável com os pés na largura dos ombros.', 'Sente-se erguido e posicione os ombros antes de puxar a alça para baixo.', 'Puxe a alça para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco firme.', 'Puxe com os cotovelos em vez de se inclinar muito para trás para mover a alça.', 'Deixe a alça subir firmemente até que os braços estejam longos, depois reajuste os ombros.']),
  ('NfP83rA', 'Extensão alternada deitada com halteres', array['Deite-se em um banco com um halter em cada mão, com as palmas voltadas uma para a outra.', 'Estenda os braços direto para cima sobre o peito, mantendo uma leve flexão nos cotovelos.', 'Posicione a parte superior dos braços no lugar antes de estender os cotovelos.', 'Mantenha a parte superior dos braços estável e estenda pelos cotovelos para mover o peso.', 'Conclua o movimento de um lado antes que o outro lado assuma o controle.', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição; alterne os lados quando necessário.']),
  ('nFUwqG6', 'Remada alta no Smith para deltoide posterior', array['Ajuste o assento ao seu corpo e, em seguida, acomode-se na máquina.', 'Segure as alças com as palmas voltadas para baixo, um pouco além da largura dos ombros.', 'Posicione o tronco e permita que os braços alcancem a frente sem curvar excessivamente.', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao seu tronco.', 'Traga os cotovelos para trás sem sacudir o tronco.', 'Estenda os braços para a frente novamente sem deixar o tronco balançar.']),
  ('ngPpyRS', 'Desenvolvimento militar sentado por trás da cabeça com barra', array['Sente-se em um banco com as costas retas e os pés apoiados.', 'Segure a barra com as palmas voltadas para baixo, um pouco além da largura dos ombros.', 'Estabilize o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as alças para longe enquanto mantém o tronco firme.', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural.', 'Abaixe o peso até a altura inicial sob controle antes de empurrar novamente.']),
  ('Nh3mvOO', 'Remada curvada com halteres com pegada supinada', array['Fique de pé com os pés na largura dos ombros e joelhos flexionados', 'Segure um halter em cada mão com as palmas voltadas para baixo e para o corpo', 'Ajuste o tronco e estique os braços para frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga o peso em direção ao tronco', 'Mantenha as palmas na pegada escolhida sem dobrar os punhos para trás', 'Estique os braços para frente novamente sem deixar o tronco balançar']),
  ('ninBEOY', 'barra fixa com pegada alternada', array['Fique de pé com os pés na largura dos ombros e joelhos flexionados', 'Segure uma barra fixa com as palmas voltadas para baixo e mãos logo acima da largura dos ombros', 'Comece de uma suspensão controlada com os ombros ativos e não soltos', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Desça até os braços ficarem estendidos sem soltar de repente do topo']),
  ('nIR4Rwl', 'Supino sentado no cabo', array['Ajuste a altura do assento e das polias em uma posição confortável', 'Sente-se no banco com as costas retas e os pés apoiados', 'Firme o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou os puxadores para longe enquanto mantém o tronco firme', 'Mantenha os punhos alinhados e use uma trajetória de ombro natural', 'Baixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('niXESDw', 'Agachamento com rosca bíceps com halteres', array['Fique de pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas voltadas para frente', 'Com as costas retas e os cotovelos próximos aos lados, expire e faça a rosca dos halteres em direção aos ombros', 'Firme o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste sua postura e respiração, depois inicie a próxima descida']),
  ('NJzBsGJ', 'Encolhimento de ombros com halteres', array['Fique de pé com os pés na largura dos ombros e segure um halter em cada mão com as palmas voltadas para o corpo', 'Mantenha os braços retos e deixe os halteres pendurados ao lado do corpo', 'Deixe os braços caírem longos e mantenha a cabeça neutra', 'Eleve os ombros em direção às orelhas sem dobrar os cotovelos ou girar os ombros', 'Levante e abaixe verticalmente sem girar os ombros', 'Traga o peso ou o corpo de volta à posição inicial sem pressa']),
  ('NKJ8o6x', 'Pelve tilt', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Coloque as mãos ao lado do corpo', 'Relaxe os ombros e encontre uma posição inicial neutra e confortável', 'Gire suavemente a pelve para achatar e relaxar a parte inferior das costas em uma pequena amplitude', 'Use uma pequena amplitude e evite forçar a parte inferior das costas contra o chão', 'Solte a inclinação suavemente e repita sem forçar a amplitude']),
  ('NL6YBwN', 'Crucifixo declinado com um braço com halter', array['Deite-se em um banco declinado com um halter em uma mão, apoiando-o na coxa', 'Use a coxa para ajudar a levantar o halter, elevando-o na largura dos ombros com a palma voltada para o tronco', 'Mantenha uma leve flexão no cotovelo e ajuste os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, junte os braços em um arco largo', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço que está trabalhando', 'Abra os braços de volta pelo mesmo arco sem deixar cair a carga; alterne os lados quando necessário']),
  ('NlfIbzq', 'Rosca scott alternada com halteres', array['Sente-se em um banco scott com um halter em cada mão e as palmas voltadas para cima', 'Apoie os braços no coxim do banco scott, permitindo que eles se estendam totalmente', 'Apoie o braço em exercício no coxim scott e deixe o cotovelo livre para dobrar', 'Faça a rosca do peso enquanto os braços permanecem em contato com o coxim', 'Termine o movimento de um lado antes que o outro lado comece', 'Desça até que os cotovelos estejam quase retos, mantendo os braços parados; alterne os lados quando necessário']),
  ('nlJsbkW', 'Rosca direta com halteres (com blaster de braço)', array['Fique em pé com um halter em cada mão e palmas viradas para a frente', 'Mantenha os cotovelos próximos ao tronco e os braços estáticos', 'Posicione os ombros e braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Desça até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('NN8nSNT', 'Tríceps testa na polia alta com corda', array['Conecte uma corda à polia alta e ajuste o peso conforme necessário', 'Fique de costas para a máquina com uma base estável e pés na largura dos ombros', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços apontados para cima e estenda os cotovelos sem estufar as costelas', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('nnmCTLN', 'Flexão de joelhos ajoelhado na máquina', array['Ajuste a máquina ao seu corpo e selecione o peso desejado', 'Ajoelhe-se na máquina virado para baixo, com os joelhos no apoio e pés presos sob as almofadas', 'Alinhe os joelhos com a borda da máquina ou banco antes de iniciar a flexão', 'Flexione os joelhos para puxar o apoio em sua direção sem levantar os quadris', 'Mantenha os quadris parados enquanto os joelhos se flexionam', 'Retorne o peso ou o corpo à posição inicial sem pressa']),
  ('NNoHCEA', 'Agachamento livre no Smith', array['Prepare a máquina Smith com a barra na altura dos ombros', 'Fique em pé com os pés na largura dos ombros e pontas levemente viradas para fora', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione quadris e joelhos para descer, mantendo os pés apoiados e joelhos alinhados com os dedos', 'Empurre para cima com peito e quadris subindo juntos; evite que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste a base e a respiração, então inicie a próxima descida']),
  ('nqs5HGV', 'Agachamento unilateral (Pistol)', array['Fique em pé com os pés na largura dos ombros e braços estendidos à frente', 'Antes de se mover, tire o pé direito do chão e estenda-o para a frente', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Estenda a perna livre à frente enquanto agacha sobre a perna de apoio, mantendo o calcanhar no chão', 'Empurre para cima com peito e quadris subindo juntos; evite que o joelho caia para dentro', 'Fique totalmente em pé, ajuste a base e a respiração, então inicie a próxima descida']),
  ('ns0SIbU', 'Supino inclinado com halteres', array['Ajuste o banco a aproximadamente 45 graus', 'Sente-se no banco com os pés apoiados e as costas firmemente pressionadas contra o encosto', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco contraído', 'Mantenha os punhos alinhados e use um caminho de movimento natural para os ombros', 'Desça o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('ntjtCfu', 'Elevação de pernas sentado com barra', array['Sente-se em um banco com as costas retas e segure uma barra sobre as coxas', 'Apoie as mãos nas laterais do banco para dar suporte', 'Contraia o abdômen e mantenha os ombros ancorados ao apoio', 'Levante as pernas contraindo o tronco e movendo nos quadris em vez de balançar', 'Termine o movimento de um lado antes que o outro lado assuma', 'Desça as pernas lentamente sem balançar ou perder a posição do tronco; alterne os lados quando necessário']),
  ('Nu7jqFE', 'Remada sentada com elástico', array['Sente-se no chão com as pernas estendidas e passe o elástico de resistência ao redor dos pés', 'Segure as pontas do elástico com as mãos e palmas voltadas uma para a outra', 'Posicione o tronco e permita que os braços alcancem a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a manopla ou peso em direção ao tronco', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Estique os braços à frente novamente sem deixar o tronco inclinar bruscamente']),
  ('nuBF9MO', 'Elevação de pernas suspensa em L', array['Suspenda-se em uma barra fixa com os braços estendidos e as palmas viradas para frente', 'Contraia o tronco e levante as pernas em direção à barra, mantendo-as esticadas', 'Contraia o abdômen e mantenha os ombros fixos no suporte', 'Levante as pernas contraindo o tronco e movimentando os quadris em vez de balançar', 'Desacelere as pernas antes que elas tirem a parte inferior das costas da posição', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco']),
  ('numr601', 'Supino vertical na máquina em pé', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure as alças com as palmas para baixo e posicione as mãos na altura do peito', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe, mantendo o tronco contraído', 'Mantenha os punhos alinhados e use um trajeto de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('nUwVh7b', 'Levantamento terra com halteres', array['Fique em pé com os pés na largura dos ombros e pontas dos pés apontadas para frente', 'Segure um halter em cada mão, com as palmas voltadas para o corpo e braços estendidos para baixo', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Empurre os quadris para trás, mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar', 'Projete os quadris para frente para ficar erguido, sem inclinar para trás no topo']),
  ('NvfE43H', 'Rosca concentrada no cabo', array['Sente-se em um banco ou cadeira com os pés apoiados e os joelhos semiflexionados', 'Segure a alça do cabo com as palmas para cima e apoie o cotovelo contra a parte interna da coxa', 'Posicione os ombros e os braços antes de flexionar os cotovelos', 'Flexione os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('nxW6BkN', 'Elevação lateral inclinado com halteres', array['Sente-se em um banco inclinado com um halter em cada mão, apoiados nas coxas', 'Recline-se no banco e levante os halteres até a altura dos ombros, com as palmas para frente', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Afaste os pesos do tronco até a altura dos ombros, mantendo os cotovelos levemente flexionados', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para as laterais sem balançar o peso']),
  ('NZ5Qqkz', 'Mergulho reverso', array['Posicione-se entre duas barras paralelas com os braços esticados e o corpo reto', 'Antes de se mover, abaixe o corpo flexionando os cotovelos até que seus braços fiquem paralelos ao chão', 'Abaixe os ombros e mantenha os cotovelos apontados majoritariamente para trás', 'Flexione os cotovelos para descer entre os suportes; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita aos ombros ficarem confortáveis', 'Empurre com as mãos para subir e ajuste os ombros antes de outra repetição']),
  ('nZZZy9m', 'Remada alta na máquina', array['Ajuste a altura do assento e a plataforma para os pés em uma posição confortável', 'Sente-se na máquina com o peito apoiado no encosto e os pés retos na plataforma', 'Posicione o tronco e permita que os braços se estendam para frente sem arredondar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao seu tronco', 'Traga os cotovelos para trás sem tracionar o tronco bruscamente', 'Estenda os braços para frente novamente sem deixar o tronco se projetar']),
  ('o17Jfkt', 'Supino inclinado na máquina', array['Ajuste a altura do assento e o ângulo do encosto na máquina articulada para uma posição confortável', 'Sente-se na máquina com as costas apoiadas no encosto e os pés firmes no chão', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe, mantendo o tronco contraído', 'Mantenha os punhos alinhados e use um trajeto de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('o1HGDSq', 'Extensão de lombar na bola suíça com as mãos atrás da cabeça', array['1) Posicione a bola suíça no chão e deite-se de bruços sobre ela, com o quadril apoiado na bola.', '2) Apoie os pés contra uma parede ou outra superfície firme para dar suporte.', '3) Firme o quadril e os pés no suporte antes de iniciar a elevação.', '4) Eleve o tronco ou as pernas até alinhá-los com o corpo, sem curvar excessivamente a região lombar.', '5) Mantenha a bola firme e use os pés para controlar o equilíbrio.', '6) Retorne o peso ou o corpo à posição inicial sem pressa.']),
  ('o1ntciW', 'Rosca martelo com barra olímpica', array['1) Fique em pé com os pés na largura dos ombros e segure uma barra olímpica com as palmas voltadas para baixo.', '2) Mantenha a barra pendurada com os braços estendidos à frente das coxas, com as palmas voltadas para o corpo.', '3) Posicione os ombros e a parte superior dos braços antes de flexionar os cotovelos.', '4) Flexione os braços com as palmas voltadas uma para a outra e os cotovelos próximos ao corpo; evite balançar para trás.', '5) Mantenha as palmas voltadas uma para a outra e os punhos retos.', '6) Abaixe até que os cotovelos estejam quase retos, mantendo a parte superior dos braços imóvel.']),
  ('O2K9Vb5', 'Paralelas com pegada aberta para peito em barras altas', array['1) Posicione-se nas barras paralelas com os braços estendidos e o corpo suspenso no ar.', '2) Incline-se ligeiramente para a frente e abaixe o corpo flexionando os cotovelos até que o peito fique logo acima das barras.', '3) Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás.', '4) Flexione os cotovelos para descer entre os suportes; pare em uma profundidade confortável para os ombros.', '5) Escolha uma profundidade que permita manter os ombros confortáveis.', '6) Pressione as mãos para subir, depois reajuste os ombros antes de outra repetição.']),
  ('O3INw8V', 'Esfinge', array['1) Posicione-se de bruços no chão com os antebraços apoiados no piso e os cotovelos diretamente sob os ombros.', '2) Contraia o abdômen e eleve o peito do chão, mantendo os antebraços e os dedos dos pés no piso.', '3) Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', '4) Desloque-se em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar.', '5) Permaneça em um alongamento leve em vez de puxar mais com impulso.', '6) Mantenha a posição com respiração constante e solte suavemente; repita do outro lado, se necessário.']),
  ('O4oIqQD', 'Remada unilateral em pé com peso corporal (com toalha)', array['1) Fique em pé com os pés na largura dos ombros, joelhos levemente flexionados e segure uma toalha com uma mão.', '2) Incline-se para a frente a partir do quadril, com a coluna firme e o core contraído.', '3) Posicione o tronco e permita que os braços se estendam para a frente sem arredondar excessivamente.', '4) Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco.', '5) Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando.', '6) Estique os braços para a frente novamente sem deixar o tronco oscilar; alterne os lados quando necessário.']),
  ('o5Jsk92', 'Crucifixo unilateral com halteres no banco', array['1) Sente-se em um banco reto com um halter em uma mão, apoiado sobre a coxa.', '2) Deite-se no banco, mantendo o halter pressionado contra a coxa.', '3) Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços.', '4) Com uma leve flexão nos cotovelos, aproxime os braços em um arco amplo.', '5) Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando.', '6) Abra os braços de volta pelo mesmo arco sem deixar o peso cair; alterne os lados quando necessário.']),
  ('o6LqKKP', 'Stiff com barra', array['1) Fique em pé com os pés na largura dos ombros e os dedos apontados para a frente.', '2) Segure a barra com as palmas voltadas para baixo e as mãos logo além da largura dos ombros.', '3) Destrave os joelhos e contraia o abdômen antes de mover o quadril para trás.', '4) Envie o quadril para trás com uma leve flexão nos joelhos, descendo o peso próximo às pernas até sentir os posteriores de coxa alongarem.', '5) Mantenha o peso próximo às pernas e pare quando as costas começarem a arredondar.', '6) Empurre o quadril para a frente para ficar em pé, sem inclinar o tronco para trás no topo.']),
  ('o80Xu9C', 'Desenvolvimento unilateral com kettlebell com amplitude estendida no chão', array['1) Comece deitado de costas no chão, com os joelhos flexionados e os pés apoiados.', '2) Segure um kettlebell em uma mão, com a palma voltada para os pés.', '3) Contraia o tronco e alinhe os punhos com os antebraços.', '4) Empurre o peso ou a alça para cima, mantendo o tronco contraído.', '5) Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando.', '6) Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando necessário.']),
  ('o8aOcrz', 'Tríceps testa inclinado no Smith', array['Ajuste o banco do Smith para que a barra fique na altura dos ombros', 'Sente-se no banco com as costas apoiadas no encosto e os pés firmes no chão', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda os cotovelos para mover o peso', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('O8Aq69u', 'Rosca inversa no banco Scott com halteres', array['Sente-se em um banco Scott com os braços apoiados no coxim e o peito contra o suporte', 'Segure um halter em cada mão com as palmas voltadas para cima', 'Posicione o braço em trabalho contra o coxim Scott e deixe o cotovelo livre para flexionar', 'Flexione o peso enquanto os braços permanecem em contato com o coxim', 'Mantenha o tronco estável e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('O8o7q4d', 'Supino com halteres na bola suíça', array['Sente-se em uma bola suíça com os pés firmes e halteres em cada mão, apoiados nas coxas', 'Caminhe com os pés para a frente com controle, rolando a bola até que sua região lombar esteja apoiada e seus joelhos em um ângulo de 90 graus', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco contraído', 'Mantenha a bola firme e use os pés para controlar o equilíbrio', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente']),
  ('O95afRA', 'Caminhada monstro', array['Coloque uma faixa de resistência ao redor dos tornozelos', 'Fique em pé com os pés na largura dos ombros e flexione levemente os joelhos', 'Fique erguido com a carga segura e os ombros nivelados', 'Caminhe em um ritmo controlado, mantendo os ombros nivelados e os passos uniformes', 'Mantenha os passos uniformes e evite inclinar-se para longe da carga', 'Pare antes que a postura falhe, coloque a carga no chão com segurança e reinicie para a próxima caminhada']),
  ('OaE7CpD', 'Rotação e inclinação dupla com kettlebell', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell na mão direita', 'Estenda o braço direito para cima, mantendo os olhos no kettlebell', 'Posicione a pelve e faça a rotação através da caixa torácica', 'Gire o tronco enquanto os quadris e a parte inferior do corpo permanecem o mais estáveis possível', 'Mantenha a rotação suave em vez de lançar os braços pelo corpo', 'Retorne pelo centro antes de girar para o outro lado']),
  ('OAguZoG', 'Rosca martelo no aparelho Scott', array['Ajuste o assento ao seu corpo e acomode-se no aparelho', 'Apoie os braços no coxim Scott, garantindo que seu peito esteja pressionado contra ele', 'Posicione o braço em trabalho contra o coxim Scott e deixe o cotovelo livre para flexionar', 'Flexione o peso enquanto seus braços permanecem em contato com o coxim', 'Mantenha as palmas das mãos voltadas uma para a outra e os punhos retos', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('obe5LMq', 'Tríceps lateral com elástico', array['Fique em pé com os pés na largura dos ombros e segure o elástico com ambas as mãos, com as palmas voltadas para baixo', 'Estenda os braços para os lados, mantendo-os paralelos ao chão', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda os cotovelos para mover o peso', 'Controle o elástico na volta em vez de deixar que ele puxe você de uma vez', 'Flexione os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('ocYc6Db', 'Desenvolvimento unilateral em pé com halteres e palma para dentro', array['Fique em pé com os pés na largura dos ombros, segurando um halter em uma mão na altura do ombro com a palma voltada para dentro', 'Contraia o tronco e mantenha a coluna em uma posição neutra e confortável', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso para longe enquanto mantém o tronco contraído', 'Mantenha ambos os ombros nivelados e resista à rotação em direção ao braço em trabalho', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente; alterne os lados quando a série exigir']),
  ('OeL23VY', 'Rosca bíceps sentado com halteres com desenvolvimento', array['Sente-se em um banco com as costas retas e os pés apoiados', 'Pegue um halter em cada mão com as palmas voltadas para a frente e os braços esticados', 'Posicione os ombros e os braços antes de dobrar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco imóvel e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase retos, mantendo os braços parados']),
  ('oHg8eop', 'Arremesso de bola medicinal acima da cabeça', array['Fique em pé com os pés na largura dos ombros, segurando uma bola medicinal com as duas mãos acima da cabeça', 'Contraia o abdômen e mantenha a coluna em uma posição neutra e confortável', 'Adote uma postura firme e deixe espaço livre suficiente para o trajeto da bola', 'Empurre a bola para longe com força, usando os braços e o tronco juntos; pegue-a ou recupere-a antes de reiniciar', 'Acompanhe o movimento com o corpo inteiro, mantendo o controle da aterrissagem ou da recepção', 'Traga o peso ou o corpo de volta à posição inicial sem pressa']),
  ('oHsrypV', 'Adução de quadril sentada no aparelho', array['Ajuste o assento ao seu corpo e acomode-se no aparelho', 'Posicione os pés nos apoios e segure nas alças para estabilidade', 'Nivele a pelve antes de mover a perna de trabalho', 'Puxe a perna de trabalho para dentro contra a resistência sem inclinar para o lado', 'Mova-se apenas até onde a pelve puder permanecer firme', 'Retorne suavemente ao início antes de repetir']),
  ('OIFMAp1', 'Remada alta unilateral sentada no aparelho', array['Ajuste o assento ao seu corpo e acomode-se no aparelho', 'Segure a alça com uma mão e mantenha a coluna em uma posição neutra e confortável', 'Posicione o tronco e permita que os braços avancem sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Mantenha ambos os ombros nivelados e evite virar-se em direção ao braço que está trabalhando', 'Estique os braços para a frente novamente sem deixar o tronco balançar; alterne os lados quando a série exigir']),
  ('OJFgZJ0', 'Extensão de tríceps com barra deitado com a barra atrás da cabeça', array['Acomode-se em um banco com os pés apoiados e a cabeça na ponta do banco', 'Pegue uma barra com as palmas voltadas para baixo, mãos na largura dos ombros e estique os braços para cima sobre o peito', 'Posicione os braços no lugar antes de estender os cotovelos', 'Mantenha os braços firmes e estenda pelos cotovelos para mover o peso', 'Mantenha os braços firmes enquanto os antebraços se movimentam', 'Dobre os cotovelos lentamente para retornar ao início da próxima repetição']),
  ('oLrKqDH', 'Corrida', array['Comece em pé, erguido, com os pés na largura dos quadris', 'Contraia o abdômen e mantenha a parte superior do corpo relaxada', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia', 'Mova-se em um ritmo repetível, mantendo o movimento suave e a respiração constante', 'Mantenha o padrão repetível conforme a velocidade aumenta', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar']),
  ('OM46QHm', 'Pull-through no cabo com corda', array['Fique de costas para a polia baixa com a corda passando entre as suas pernas', 'Segure o acessório de corda com as duas mãos e dê um passo à frente, gerando tensão no cabo', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Empurre os quadris para trás mantendo a carga próxima e a coluna firme', 'Mantenha o peso próximo às pernas e pare quando as costas começarem a curvar', 'Empurre os quadris para frente para ficar em pé sem inclinar para trás no topo']),
  ('OmQ8w0p', 'Remada rotacional com palma no cabo', array['Conecte uma alça a uma máquina de cabo na altura da cintura', 'Fique de frente para a máquina em uma postura estável com os pés na largura dos ombros', 'Posicione o tronco e permita que os braços avancem sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estique os braços para a frente novamente sem deixar o tronco balançar']),
  ('omsF3RN', 'Tríceps francês unilateral com elástico', array['Fique em pé com os pés na largura dos ombros e segure o elástico com as duas mãos, com as palmas para baixo', 'Estenda os braços reto para os lados, mantendo-os paralelos ao chão', 'Posicione os braços antes de estender os cotovelos', 'Mantenha os braços firmes e estenda através dos cotovelos para mover a carga', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Flexione os cotovelos devagar para retornar ao início da próxima repetição']),
  ('oMwyl17', 'Stiff com barra', array['Fique em pé com os pés na largura dos ombros e as pontas dos pés apontadas para a frente', 'Segure a barra com as palmas para baixo e as mãos um pouco além da largura dos ombros', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Envie os quadris para trás com uma leve flexão nos joelhos, descendo a carga perto das pernas até sentir os posteriores de coxa', 'Mantenha o peso perto das pernas e pare quando as costas começarem a arredondar', 'Empurre os quadris para a frente para ficar totalmente em pé, sem inclinar o tronco para trás no topo']),
  ('oMypNrz', 'Alongamento de quadril com rolo', array['Comece sentando no chão com as pernas estendidas à sua frente', 'Coloque o rolo sob os glúteos, logo acima dos joelhos', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte devagar e repita do outro lado, se necessário']),
  ('ookVu2D', 'Pullover com halter e extensão de quadril na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e o halter descansando nas coxas', 'Com controle, caminhe com os pés para a frente, rolando a bola suíça pelas costas até que a cabeça, o pescoço e a parte superior das costas fiquem apoiados na bola', 'Abaixe as costelas e mantenha uma leve flexão nos cotovelos antes de descer o peso', 'Desça o peso em um arco atrás da cabeça até sentir um alongamento confortável nos ombros', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio', 'Puxe o peso de volta sobre o peito pelo mesmo arco, sem levantar as costelas']),
  ('oom75KC', 'Stiff com halteres', array['Fique em pé com os pés na largura dos ombros, segurando um halter em cada mão com as palmas para baixo', 'Com as costas retas e o core contraído, flexione o quadril e desça os halteres em direção ao chão, permitindo que o tronco se incline para a frente', 'Destrave os joelhos e contraia o abdômen antes de mover os quadris para trás', 'Envie os quadris para trás com uma leve flexão nos joelhos, descendo a carga perto das pernas até sentir os posteriores de coxa', 'Mantenha o peso perto das pernas e pare quando as costas começarem a arredondar', 'Empurre os quadris para a frente para ficar totalmente em pé, sem inclinar o tronco para trás no topo']),
  ('OPqShYN', 'Extensão de quadril na máquina', array['Ajuste a máquina para o seu corpo e sente-se nela com as costas apoiadas no encosto', 'Apoie os pés nos suportes e segure nas alças para ter estabilidade', 'Apoie bem os pés e evite estufar as costelas enquanto os quadris se prepararam para subir', 'Pressione com os pés e eleve os quadris até que o seu tronco e as suas coxas fiquem alinhados', 'Pare quando os quadris alinharem com o tronco e não arqueie mais a região lombar', 'Abaixe os quadris de forma constante e mantenha os pés apoiados para o próximo movimento']),
  ('OQ1otBN', 'Puxada frontal cruzada no cabo', array['Conecte um puxador a cada lado de um aparelho de cabo na altura dos ombros', 'Posicione-se no meio do aparelho com os pés na largura dos ombros', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Traga os puxadores cruzando a frente do seu peito em um arco amplo, mantendo uma leve flexão nos cotovelos', 'Mantenha o ângulo dos cotovelos quase inalterado durante o arco', 'Abra os braços de volta pelo mesmo arco sem deixar a carga cair']),
  ('oQRJYkC', 'Alongamento lateral de pescoço', array['Fique em pé ou sentado com a coluna ereta e os ombros relaxados', 'Incline a cabeça para a direita, aproximando a orelha direita do ombro direito', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Aproxime-se do alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha-se em um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte devagar e repita do outro lado, se necessário']),
  ('oR7O9LW', 'Agachamento com barra (de joelhos)', array['Comece ajoelhado no chão com os joelhos na largura dos quadris e os dedos dos pés apontados para a frente', 'Posicione uma barra sobre os ombros, segurando-a com as palmas para baixo e as mãos um pouco além da largura dos ombros', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste sua base e respiração, depois comece a próxima descida']),
  ('OrETs32', 'Hiperextensão reversa no banco plano', array['Posicione-se de bruços em um banco plano com os quadris na borda e as pernas penduradas para fora do banco', 'Use o banco para estabilidade', 'Fixe os quadris e os pés no apoio antes de levantar', 'Eleve o tronco ou as pernas até que fiquem alinhados com o corpo, sem curvar excessivamente a parte inferior das costas', 'Termine em uma linha corporal reta, antes que a parte inferior das costas arqueie demais', 'Retorne o peso ou o corpo à posição inicial sem pressa']),
  ('oROuvrX', 'Remada unilateral na máquina', array['Ajuste o assento ao seu corpo e acomode-se na máquina', 'Segure os puxadores com as palmas para baixo e mantenha a coluna em uma posição neutra e confortável', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga o puxador ou peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos com o tronco', 'Estenda os brazos para a frente novamente sem deixar o tronco balançar']),
  ('osdXT3K', 'Desenvolvimento unilateral com kettlebell', array['Fique em pé com os pés na largura dos ombros, segurando um kettlebell em uma das mãos na altura do ombro', 'Flexione levemente os joelhos e contraia o tronco', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou puxadores para cima mantendo o tronco contraído', 'Mantenha ambos os ombros nivelados e evite virar em direção ao braço que está trabalhando', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando necessário']),
