  ('PKlXuJW', 'Abdominal com elástico', array['Prenda o elástico firmemente a um ponto de ancoragem estável', 'Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Posicione a pelve e mantenha o pescoço relaxado antes de subir', 'Enrole a caixa torácica em direção à pelve, deixando o abdômen mover o tronco', 'Controle o elástico na volta em vez de deixar que ele puxe você rapidamente', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('pkSoCW9', 'Agachamento Jefferson com barra', array['Fique em pé com os pés na largura dos ombros e as pontas dos pés levemente viradas para fora', 'Segure a barra com as palmas voltadas para baixo, apoiando-a na frente do corpo, logo abaixo da cintura', 'Firme o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés apoiados e os joelhos alinhados com os dedos', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos caiam para dentro', 'Fique totalmente em pé, ajuste a base e a respiração, depois inicie a próxima descida']),
  ('pM07UxU', 'Kipping muscle-up', array['Fique pendurado em uma barra fixa com as palmas voltadas para baixo e mãos logo além da largura dos ombros', 'Contraia o tronco e use um movimento de balanço para gerar impulso', 'Comece de uma suspensão controlada com os ombros ativos e não relaxados', 'Puxe os cotovelos para baixo e traga a parte superior do peito em direção à barra sem chutar as pernas', 'Evite balançar as pernas para passar da barra', 'Desça com os braços estendidos sem cair repentinamente do topo']),
  ('PM1PZjg', 'Afundo com salto', array['Fique em pé com os pés na largura dos ombros', 'Dê um passo à frente com o pé direito, abaixando o corpo em uma posição de afundo', 'Abra bem a base para se equilibrar antes de flexionar qualquer um dos joelhos', 'Avance para o movimento e flexione ambos os joelhos, mantendo o pé da frente apoiado', 'Mantenha o pé da frente apoiado e evite que o joelho vire para dentro', 'Empurre o pé da frente para voltar ao início e troque de perna conforme planejado']),
  ('pmnrOp0', 'Puxada unilateral ajoelhada com elástico', array['Prenda o elástico a um ponto de ancoragem firme acima da sua cabeça', 'Ajoelhe-se e segure o elástico com uma mão, com a palma voltada para baixo', 'Sente-se erguido e ajuste os ombros antes de puxar a alça para baixo', 'Puxe a alça para baixo levando os cotovelos em direção às costelas; mantenha o tronco firme', 'Mantenha ambos os ombros nivelados e resista a girar em direção ao braço que trabalha', 'Deixe a alça subir constantemente até os braços estarem estendidos, ajuste os ombros e troque de lado quando necessário']),
  ('pNIKolI', 'Alongamento de tríceps sentado na bola suíça', array['Sente-se em uma bola suíça com os pés apoiados e as costas retas', 'Pegue um halter com uma mão e estenda o braço para cima acima da cabeça', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Vá em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar', 'Mantenha a bola firme e use os pés para controlar o seu equilíbrio', 'Mantenha a posição com respiração constante e solte suavemente; repita do outro lado se necessário']),
  ('PNtsX17', 'Remada alta sentada com pegada supinada no cabo', array['Sente-se no aparelho de frente para a polia com os pés apoiados', 'Segure o acessório do cabo com as palmas voltadas para cima e as mãos na largura dos ombros', 'Posicione o tronco e permita que os braços se esticem para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e leve a alça ou o peso em direção ao tronco', 'Mantenha as palmas na pegada escolhida sem dobrar os punhos para trás', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('PnZJIrk', 'Paralela com apoio de joelhos e pegada aberta (ajoelhado)', array['Ajuste o aparelho na altura desejada e apoie os joelhos na almofada', 'Segure as manoplas com pegada aberta e mantenha os cotovelos semiflexionados', 'Abaixe os ombros e mantenha os cotovelos apontados principalmente para trás', 'Dobre os cotovelos para descer entre os suportes; pare em uma profundidade confortável para os ombros', 'Escolha uma profundidade que permita manter os ombros confortáveis', 'Empurre pelas mãos para subir, depois ajuste os ombros antes de outra repetição']),
  ('pP8wP2P', 'Supino com halteres e pegada neutra', array['Acomode-se em um banco com os pés apoiados e as costas pressionadas contra o banco', 'Pegue um halter em cada mão com pegada neutra (palmas voltadas uma para a outra) e os braços esticados para cima sobre o peito', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças mantendo o tronco firme', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial sob controle antes de empurrar novamente']),
  ('pQ0Mx1Z', 'Bandeira humana', array['Comece segurando um poste vertical com as duas mãos, palmas voltadas uma para a outra, e braços esticados', 'Contraia o tronco e tire os pés do chão, mantendo-os retos', 'Contraia o abdômen e encontre uma posição que você consiga manter sem prender a respiração', 'Contraia a região central e segure a posição enquanto respira normalmente', 'Continue respirando de forma constante enquanto mantém a mesma linha corporal', 'Mantenha a forma pelo tempo planejado e saia dela com controle']),
  ('PQ2AtC3', 'Abdominal com elevação de pernas sentado no aparelho', array['Sente-se no aparelho com as costas contra o encosto e os pés nos apoios', 'Segure as manoplas ou barras laterais para ter estabilidade', 'Posicione a pelve e mantenha o pescoço relaxado antes de enrolar para cima', 'Enrole a caixa torácica em direção à pelve, deixando o abdômen mover o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('PQcUlDi', 'Crucifixo invertido deitado com cabo', array['Conecte um puxador tipo D a uma polia baixa e posicione-se de bruços em um banco reto', 'Segure o puxador em cada mão, com as palmas voltadas para baixo, e estique os braços diretamente à sua frente', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Abra os braços para fora e para trás com uma leve flexão nos cotovelos, juntando as escápulas', 'Mantenha o ângulo do cotovelo quase inalterado durante o arco', 'Abra os braços para trás seguindo o mesmo arco sem deixar a carga cair']),
  ('PQStVXH', 'Remada alta com cabo', array['Encaixe uma barra reta na polia na altura do peito', 'Fique de frente para o aparelho em uma base estável com os pés na largura dos ombros', 'Posicione o tronco e permita que os braços se esticem para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e leve a alça ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem trancos no tronco', 'Estenda os braços para a frente novamente sem deixar o tronco balançar']),
  ('Pr9Rhf4', 'Crucifixo em pé com cabo', array['Conecte os puxadores aos cabos na altura do peito', 'Fique em pé com os pés na largura dos ombros, de costas para a máquina de cabo', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços', 'Com uma leve flexão nos cotovelos, junte os braços em um arco amplo', 'Mantenha o ângulo do cotovelo quase inalterado durante o arco', 'Abra os braços para trás seguindo o mesmo arco sem deixar a carga cair']),
  ('prbWx1D', 'Crucifixo invertido com rotação de halteres', array['Fique em pé com os pés na largura dos ombros e segure um halter em cada mão, com as palmas voltadas para dentro.', 'Flexione levemente os joelhos e incline o tronco para frente a partir do quadril, mantendo a coluna firme e o peito estufado.', 'Mantenha uma leve flexão nos cotovelos e posicione os ombros antes de mover os braços.', 'Abra os braços para fora e para trás com uma leve flexão nos cotovelos, aproximando as escápulas.', 'Mantenha o ângulo dos cotovelos quase inalterado durante todo o arco de movimento.', 'Abra os braços para trás seguindo o mesmo arco sem deixar o peso cair.']),
  ('PrQbjvB', 'Flexão com corrida', array['Comece em posição de flexão com as mãos na largura dos ombros e o corpo em linha reta.', 'Abaixe o peito em direção ao chão flexionando os cotovelos, mantendo o corpo reto.', 'Comece em um ritmo que permita que os pés e os braços se movam em sincronia.', 'Mude de posição em um ritmo repetível, mantendo o movimento suave e a respiração constante.', 'Mantenha o padrão repetível conforme a velocidade aumenta.', 'Mantenha o ritmo pelo intervalo planejado, diminuindo a velocidade se a forma começar a falhar.']),
  ('PskORrA', 'Tríceps na polia com barra reta', array['Conecte uma barra reta a um aparelho de polia alta.', 'Fique de frente para o aparelho com os pés na largura dos ombros e uma leve flexão nos joelhos.', 'Fique a uma distância suficiente da pilha de pesos para que o cabo fique esticado.', 'Mantenha os cotovelos próximos às costelas e estique os braços contra o cabo.', 'Mantenha os cotovelos próximos ao corpo em vez de deixar os ombros balançarem.', 'Retorne suavemente à posição inicial antes de repetir.']),
  ('PSlvNMs', 'Flexão com sobrecarga', array['Comece em posição de prancha alta com as mãos logo acima da largura dos ombros e os pés juntos.', 'Abaixe o peito em direção ao chão, mantendo os cotovelos próximos ao corpo.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em uma só linha.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos se flexionam.', 'Empurre o corpo de volta para cima com os braços estendidos, mantendo a linha do corpo intacta.']),
  ('PsVS1QP', 'Arremesso e recepção de medicine ball acima da cabeça', array['Fique em pé com os pés na largura dos ombros, segurando uma medicine ball com as duas mãos na altura do peito.', 'Flexione levemente os joelhos e contraia o tronco.', 'Contraia o abdômen e estabilize-se em uma posição inicial firme.', 'Mova-se pelo trajeto pretendido sob controle, mantendo as articulações alinhadas com a resistência.', 'Mantenha o movimento controlado por toda a amplitude.', 'Retorne pelo mesmo caminho em um ritmo controlado.']),
  ('pvBMLHA', 'Flexão plus', array['Comece em posição de prancha alta com as mãos logo acima da largura dos ombros e o corpo em linha reta da cabeça aos calcanhares.', 'Abaixe o corpo em direção ao chão flexionando os cotovelos, mantendo-os próximos às laterais do corpo.', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos.', 'Flexione os cotovelos para abaixar o peito enquanto mantém o corpo em uma só linha.', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos se flexionam.', 'Empurre o corpo de volta para cima com os braços estendidos, mantendo a linha do corpo intacta.']),
  ('pwt0pnM', 'Remada alta sentada na polia com barra V', array['Sente-se no aparelho de polia com os pés apoiados e os joelhos levemente flexionados.', 'Segure o acessório em V com as palmas voltadas para baixo, palmas voltadas uma para a outra e as mãos na largura dos ombros.', 'Posicione o tronco e permita que os braços se estendam para frente sem arredondar excessivamente.', 'Puxe os cotovelos para trás e traga a alça ou o peso em direção ao tronco.', 'Traga os cotovelos para trás sem dar trancos com o tronco.', 'Estique os quais para frente novamente sem deixar o tronco balançar.']),
  ('pX9Elbe', 'Supino com medicine ball e saída para corrida', array['Fique em pé com os pés na largura dos ombros, segurando uma medicine ball na altura do peito.', 'Dê um passo à frente com o pé direito e, simultaneamente, empurre a medicine ball para frente, estendendo completamente os braços.', 'Adote uma base firme e deixe espaço livre suficiente para o peso se deslocar.', 'Empurre a bola para longe com força, usando os braços e o tronco juntos; pegue-a ou recupere-a antes de reiniciar.', 'Acompanhe o movimento com o corpo inteiro, mantendo o controle da aterrissagem ou da recepção.', 'Traga o peso ou o corpo de volta à posição inicial sem pressa.']),
  ('PXTIwgu', 'Elevação de pernas estendidas na barra', array['Suspenda-se em uma barra fixa com os braços estendidos e as pernas para baixo', 'Contraia o tronco e levante as pernas à sua frente até ficarem paralelas ao solo', 'Contraia o abdômen e mantenha os ombros firmes no apoio', 'Levante as pernas contraindo o tronco e movendo os quadris em vez de balançar', 'Desacelere as pernas antes que elas tirem a lombar da posição', 'Abaixe as pernas lentamente sem balançar ou perder a posição do tronco']),
  ('py1HSzx', 'Afundo lateral com barra', array['Fique em pé com os pés na largura dos ombros, segurando uma barra na parte superior das costas', 'Dê um passo largo para o lado com o pé direito, mantendo o pé esquerdo fixo', 'Ajuste sua base com largura suficiente para se equilibrar antes de flexionar qualquer joelho', 'Inicie o movimento e flexione ambos os joelhos, mantendo o pé da frente fixo', 'Mantenha o pé da frente fixo e evite colapsar o joelho para dentro', 'Empurre com o pé da frente para retornar ao início e alterne as pernas conforme planejado']),
  ('PzNxakt', 'Alongamento de panturrilha na parede com as mãos', array['Fique de frente para uma parede com os pés na largura dos quadris', 'Apoie as mãos na parede na altura dos ombros', 'Estabeleça-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Aproxime-se do alongamento até sentir uma tensão leve, continue respirando e evite saltar', 'Mantenha um alongamento leve em vez de puxar mais com impulso', 'Segure a posição com respiração constante, solte devagar e repita do outro lado, se necessário']),
  ('PzQanLE', 'Desenvolvimento para ombros no cabo', array['Ajuste a polia do cabo para que as alças fiquem na altura dos ombros', 'Fique de costas para a máquina em uma base estável com os pés na largura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as alças para longe, mantendo o tronco contraído', 'Mantenha os punhos alinhados e use uma trajetória de ombro que pareça natural', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente']),
  ('pZwUsKB', 'Alongamento cruz de ferro', array['Deite-se de costas com os braços estendidos para os lados', 'Eleve as pernas em direção ao teto, mantendo-as estendidas', 'Comece com uma carga gerenciável e uma pequena flexão nos cotovelos', 'Abra os braços para os lados formando um T e traga-os de volta com controle', 'Pare perto da altura dos ombros em vez de encolher os ombros para subir mais', 'Abaixe os braços lentamente para os lados sem balançar o peso']),
  ('q2ADGqV', 'Abdominal lateral no cabo', array['Conecte uma alça a uma polia baixa e fique de lado para a máquina', 'Segure a alça com a mão mais afastada da máquina e coloque a outra mão no quadril', 'Ajuste a pelve e mantenha o pescoço relaxado antes de flexionar para cima', 'Flexione a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito e mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima flexão']),
  ('Q2Eu1Ax', 'Pullover deitado com extensão no cabo (com corda)', array['Conecte uma corda à polia alta de uma máquina de cabo', 'Deite-se em um banco com a cabeça voltada para a máquina de cabo', 'Abaixe as costelas e mantenha uma pequena flexão nos cotovelos antes de baixar o peso', 'Abaixe o peso em arco atrás da cabeça até sentir um alongamento confortável nos ombros', 'Mantenha as costelas abaixadas enquanto os braços passam por cima da cabeça', 'Puxe o peso de volta sobre o peito pelo mesmo arco, sem levantar as costelas']),
  ('Q497lAE', 'Flexão pliométrica', array['Comece em posição de prancha alta com as mãos logo além da largura dos ombros', 'Abaixe o peito em direção ao chão, mantendo os cotovelos próximos ao corpo', 'Contraia o abdômen e os glúteos para que ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para baixar o peito enquanto mantém o corpo alinhado', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta para os braços estendidos, mantendo a linha do corpo intacta']),
  ('Q4DSJPC', 'Remada unilateral noSmith', array['Ajuste a altura da barra do aparelho smith na altura da cintura', 'Posicione-se de frente para o smith com uma base estável e os pés na largura dos ombros', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a manopla ou o peso em direção ao seu tronco', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Estenda os braços para a frente novamente sem deixar o tronco balançar; alterne os lados quando a série exigir']),
  ('Q6bvyen', 'Elevação de pernas e quadril com rotação suspensa', array['Suspenda-se em uma barra fixa com os braços estendidos e as pernas esticadas', 'Contraia o abdômen e eleve as pernas em direção ao peito, mantendo-as retas', 'Apoie os pés e evite estufar as costelas enquanto o quadril se prepara para subir', 'Pressione através dos pés e eleve o quadril até que o seu tronco e as coxas fiquem alinhados', 'Pare quando o quadril estiver alinhado com o tronco; não arqueie mais a região lombar', 'Abaixe o quadril de forma controlada e mantenha os pés apoiados para a próxima repetição']),
  ('q6y3OhV', 'Rosca bicep na máquina', array['Ajuste o assento ao seu corpo e depois acomode-se na máquina', 'Segure as manoplas com as palmas voltadas para cima e mantenha os cotovelos próximos às costelas', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços imóvel']),
  ('q7qkONO', 'Desenvolvimento com halteres sentado alternado', array['Sente-se em um banco com as costas retas e os pés apoiados no chão', 'Pegue um halter em cada mão, com as palmas voltadas para dentro, e levante-os até a altura dos ombros', 'Contraia o tronco e alinhe os punhos com os antebraços', 'Empurre o peso ou as manoplas para cima enquanto mantém o tronco contraído', 'Conclua o movimento de um lado antes que o outro lado inicie', 'Abaixe o peso até a altura inicial de forma controlada antes de empurrar novamente; alterne os lados quando a série exigir']),
  ('q8aHNoF', 'Rosca de punho unilateral com halter', array['Sente-se em um banco ou cadeira com os pés apoiados no chão', 'Pegue um halter em uma mão com a palma voltada para cima, apoiando o antebraço na coxa', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão e do antebraço suportem a carga', 'Movimente apenas os punhos ou os dedos enquanto os antebraços permanecem apoiados e imóveis', 'Mantenha ambos os ombros nivelados e evite girar em direção ao braço que está trabalhando', 'Retorne à posição inicial de forma suave, sem deixar o peso cair das mãos; alterne os lados quando a série exigir']),
  ('Qa55kX1', 'Agachamento hack na máquina', array['Ajuste a máquina hack para uma posição confortável para a sua altura', 'Fique de pé e posicione os pés na largura dos ombros na plataforma, com as pontas dos pés levemente voltadas para fora', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para abaixar, mantendo os pés apoiados no chão e os joelhos alinhados com as pontas dos pés', 'Empurre para cima com o peito e o quadril subindo juntos; evite que os joelhos desabem para dentro', 'Fique completamente em pé, ajuste sua postura e respiração, e então inicie a próxima descida']),
  ('qAmNMJY', 'Rosca alta com halteres', array['Fique em pé com um halter em cada mão, com as palmas voltadas para a frente', 'Deixe os cotovelos fazerem o movimento enquanto a parte superior dos braços permanece no lugar e flexione os halteres o mais alto possível enquanto contrai os bíceps', 'Posicione os ombros e a parte superior dos braços antes de dobrar os cotovelos', 'Dobre os cotovelos para trazer o peso em direção aos ombros sem balançar o tronco', 'Mantenha o tronco firme e deixe a flexão do cotovelo levantar o peso', 'Abaixe até que os cotovelos estejam quase esticados, mantendo a parte superior dos braços imóvel']),
  ('qatbkEd', 'Flexão lateral com cabo (na bola bosu)', array['Fique em pé com os pés na largura dos ombros, segurando uma manopla do cabo em uma mão', 'Coloque a outra mão no quadril', 'Fique de pé ou sentado erguido com a pelve voltada para a frente', 'Incline-se lateralmente pela cintura sem girar ou deixar o quadril se deslocar', 'Deixe a lateral do tronco trabalhar; não gire nem desloque o quadril', 'Retorne pelo mesmo caminho em um ritmo controlado']),
  ('qaZVsGk', 'Toques alternados nos calcanhares', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Estique os braços para as laterais, paralelos ao solo', 'Fique em pé ou sentado ereto com a pelve voltada para a frente', 'Incline o tronco para o lado na cintura, sem torcer ou deixar os quadris se deslocarem', 'Conclua o movimento de um lado antes de iniciar o outro', 'Retorne o peso ou o corpo à posição inicial sem pressa; alterne os lados quando necessário']),
  ('qBcKorM', 'Alongamento de agachamento em quatro apoios', array['Fique de joelhos e apoie as mãos no chão diretamente sob os ombros e os joelhos sob os quadris', 'Estique uma perna para trás, mantendo o joelho flexionando e o pé flexionado', 'Posicione-se na posição inicial e respire calmamente antes de aprofundar o movimento', 'Aproxime-se do alongamento até sentir uma leve tensão; continue respirando e evite balançar', 'Mantenha um alongamento leve em vez de puxar mais com impulso', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário']),
  ('qBl14UC', 'Flexão na parede', array['Fique de frente para uma parede, a cerca de um comprimento de braço', 'Coloque as mãos na parede na altura dos ombros, um pouco além da largura dos ombros', 'Contraia o abdômen e os glúteos para que os ombros, quadris e tornozelos se movam juntos', 'Flexione os cotovelos para abaixar o peito, mantendo o corpo em linha reta', 'Mantenha a cabeça alinhada com a coluna enquanto os cotovelos flexionam', 'Empurre de volta com os braços esticados, mantendo a linha do corpo intacta']),
  ('QChZi3x', 'Agachamento com elevação dos braços acima da cabeça', array['Fique em pé com os pés na largura dos ombros e os dedos ligeiramente virados para fora', 'Antes de se mover, abaixe o corpo em posição de agachamento flexionando os joelhos e empurrando os quadris para trás', 'Contraia o abdômen e distribua a pressão por todo o pé', 'Flexione os quadris e os joelhos para descer, mantendo os pés firmes e os joelhos alinhados com os dedos dos pés', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos desabem para dentro', 'Fique totalmente em pé, ajuste a base e a respiração, depois inicie a próxima descida']),
  ('qcNN2FN', 'Elevação de quadril deitada', array['Deite-se de costas com os joelhos flexionados e os pés apoiados', 'Posicione as mãos ao lado do corpo, com as palmas voltadas para baixo', 'Posicione a pelve e mantenha o pescoço relaxado antes de curvar para cima', 'Enrole a caixa torácica em direção à pelve, permitindo que o abdômen mova o tronco', 'Deixe um pequeno espaço entre o queixo e o peito; mantenha o movimento no tronco', 'Abaixe os ombros ou o tronco com controle antes da próxima curvatura']),
  ('qCNVnaU', 'Pressão de panturrilha no leg press a 45°', array['Ajuste a máquina de leg press para um ângulo de 45 graus', 'Coloque os pés na plataforma com os dedos apontados para a frente', 'Permita que os tornozelos se movam livremente enquanto o restante do corpo permanece imóvel', 'Eleve-se na ponta dos pés, levantando os calcanhares o máximo que puder sem balançar', 'Faça uma pausa no topo sem girar os tornozelos para fora', 'Abaixe os calcanhares em um ritmo controlado antes de subir novamente']),
  ('qcY50ZD', 'Remada sentada com pegada aberta no cabo', array['Sente-se na máquina de remada com os pés apoiados e os joelhos levemente flexionados', 'Segure a barra com uma pegada pronada aberta, com as palmas voltadas para baixo', 'Posicione o tronco e permita que os braços se estendam para a frente sem curvar excessivamente', 'Puxe os cotovelos para trás e traga a barra ou o peso em direção ao tronco', 'Traga os cotovelos para trás sem dar trancos no tronco', 'Estique os braços para a frente novamente sem deixar o tronco balançar']),
  ('qDnGfDb', 'Rosca punho reversa com barra', array['Apoie ambos os pés no chão enquanto estiver sentado em um banco, com os joelhos flexionados', 'Segure uma barra com as palmas voltadas para baixo e as mãos na largura dos ombros', 'Mantenha os cotovelos relaxados para que os pequenos músculos da mão ou do antebraço suportem a carga', 'Movimente os punhos ou os dedos enquanto os antebraços permanecem apoiados e imóveis', 'Use uma amplitude pequena e suave sem balançar os cotovelos', 'Retorne suavemente ao início sem deixar a carga escapar das mãos']),
  ('qdRxqCj', 'Puxada frontal (com barra para dorsais)', array['Ajuste a altura do assento para que suas coxas fiquem paralelas ao chão e seus pés fiquem apoiados no chão.', 'Segure a barra com as palmas voltadas para baixo, logo além da largura dos ombros.', 'Sente-se erguido e ajuste os ombros antes de puxar a alça para baixo.', 'Puxe a alça para baixo direcionando os cotovelos em direção às costelas; mantenha o tronco estável.', 'Puxe com os cotovelos em vez de se inclinar muito para trás para mover a alça.', 'Deixe a alça subir firmemente até que os braços estejam estendidos, depois ajuste os ombros.']),
  ('qEse6fe', 'Flexão com toque no ombro', array['Comece em uma posição de prancha alta com as mãos logo além da largura dos ombros e seu corpo em linha reta da cabeça aos calcanhares.', 'Abaixe o corpo em direção ao chão dobrando os cotovelos, mantendo-os próximos aos lados.', 'Contraia o tronco levemente antes de mover um membro.', 'Mova o braço ou a perna de trabalho mantendo o tronco estável e a respiração constante.', 'Evite que a pelve balance enquanto o braço ou a perna se movem.', 'Ajuste sua postura antes de trocar de lado ou iniciar a próxima repetição.']),
  ('QfAKy1G', 'Desenvolvimento cubano com halteres', array['Fique de pé e posicione os pés na largura dos ombros, segurando um halter em cada mão na altura dos ombros com as palmas voltadas para baixo.', 'Com o core ativado e os cotovelos flexionados, empurre os halteres para cima e acima da cabeça até que seus braços estejam retos.', 'Contraia o tronco e alinhe os punhos com os antebraços.', 'Empurre o peso ou as alças para longe, mantendo o tronco contraído.', 'Mantenha os punhos alinhados e use um trajeto de ombro que pareça natural.', 'Abaixe o peso até a altura inicial com controle antes de empurrar novamente.']),
  ('qFHvMnv', 'Agachamento dinâmico com barra', array['Fique de pé e posicione os pés na largura dos ombros, com os dedos levemente virados para fora.', 'Apoie a barra na parte superior das costas e faça uma pegada firme.', 'Contraia o abdômen e distribua a pressão por todo o pé.', 'Flexione os quadris e joelhos para abaixar, mantendo os pés apoiados e os joelhos alinhados com os dedos dos pés.', 'Empurre para cima com o peito e os quadris subindo juntos; evite que os joelhos fechem para dentro.', 'Fique totalmente em pé, ajuste sua base e respiração, depois inicie a próxima descida.']),
  ('QFmz6ch', 'Alongamento sentado para lombar', array['Sente-se na borda de uma cadeira com os pés apoiados.', 'Coloque as mãos nas coxas ou nas laterais da cadeira para apoio.', 'Acomode-se na posição inicial e respire calmamente antes de aprofundar o movimento.', 'Vá em direção ao alongamento até sentir uma tensão leve; continue respirando e evite balançar.', 'Permaneça em um alongamento leve em vez de puxar mais com impulso.', 'Mantenha a posição com respiração constante, depois solte suavemente; repita do outro lado, se necessário.']),
  ('qFpAkpP', 'Rotação em pé com cabo', array['Fique de frente para a máquina de cabo em uma postura estável com os pés na largura dos ombros.', 'Segure a alça do cabo com as duas mãos e posicione-a na altura da cintura.', 'Ajuste a pelve e faça a rotação através da caixa torácica.', 'Gire através do tronco enquanto os quadris e a parte inferior do corpo permanecem o mais estáveis possível.', 'Mantenha a rotação suave em vez de lançar os braços através do corpo.', 'Retorne pelo centro antes de girar para o outro lado.']),
  ('qg2PGl6', 'Elevação pélvica com barra no banco', array['Comece sentando na borda de um banco com a parte superior das costas apoiada nele e os pés firmes, na largura dos quadris.', 'Posicione uma barra sobre seus quadris, segurando-a firmemente com as duas mãos.', 'Apoie os pés e evite que as costelas se expandam enquanto os quadris se preparem para subir.', 'Empurre através dos pés e eleve os quadris até que seu torso e coxas fiquem alinhados.', 'Pare quando os quadris se alinharem com o torso; não arqueie mais a região lombar.', 'Abaixe os quadris firmemente e mantenha os pés apoiados para a próxima elevação.']),
  ('qi996YS', 'Agachamento frontal com pegada de arremesso', array['Comece em pé com os pés na largura dos ombros e a barra apoiada na parte superior do peito, com os cotovelos apontados para a frente.', 'Antes de se mover, abaixe o corpo dobrando os joelhos e empurrando os quadris para trás, como se estivesse sentando em uma cadeira.', 'Contraia antes de puxar e mantenha a carga próxima ao corpo.', 'Empurre através das pernas e quadris, depois guie o peso para a posição de recebimento.', 'Receba a carga com o torso contraído e os pés estáveis.', 'Fique totalmente em pé para finalizar, depois abaixe o peso com controle antes da próxima repetição.'])
